function parseAge(text: any): any {
  const n = Number(text);
  return Number.isInteger(n) && n >= 0 ? n : "invalid";
}
for (const t of ["31", "-2", "x"]) {
  const r = parseAge(t);
  console.log(r === "invalid" ? `${t}: rejected` : `${t}: next year ${r + 1}`);
}

